        seen, todo = set(), [start]
        while todo:
            c = todo.pop()
            if c not in seen:
                seen.add(c)
                todo.extend(parents[c])
        return seen

    common = ancestors(a) & ancestors(b)
    # Remove every commit that is a proper ancestor of another common ancestor.
